"use client"

import { ChangeEmailCard } from "@/components/settings/change-email-card"
import { ProfileCard } from "@/components/settings/profile-card"
import { cn } from "@/lib/utils"

/**
 * Account settings panel: profile and email. Reusable on its own when you only
 * need the account section.
 */
export function AccountTab({ className }: { className?: string }) {
  return (
    <div className={cn("flex flex-col gap-4 md:gap-6", className)}>
      <ProfileCard />
      <ChangeEmailCard />
    </div>
  )
}

"use client"

import { ChangePasswordCard } from "@/components/settings/change-password-card"
import { LinkedAccountsCard } from "@/components/settings/linked-accounts-card"
import { PasskeysCard } from "@/components/settings/passkeys-card"
import { SessionsCard } from "@/components/settings/sessions-card"
import { cn } from "@/lib/utils"

export type SecurityTabProps = {
  className?: string
  /** Hide the passkeys card (e.g. when the passkey plugin is not enabled). */
  hidePasskeys?: boolean
  /** Hide the linked social accounts card. */
  hideLinkedAccounts?: boolean
}

/**
 * Security settings panel: password, passkeys, active sessions and linked
 * accounts. Reusable on its own; individual cards can also be used directly.
 */
export function SecurityTab({ className, hidePasskeys, hideLinkedAccounts }: SecurityTabProps) {
  return (
    <div className={cn("flex flex-col gap-4 md:gap-6", className)}>
      <ChangePasswordCard />
      {!hidePasskeys && <PasskeysCard />}
      <SessionsCard />
      {!hideLinkedAccounts && <LinkedAccountsCard />}
    </div>
  )
}

"use client"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Skeleton } from "@/components/ui/skeleton"
import { authClient } from "@/lib/auth-client"
import { useRef, useState, useTransition } from "react"

/**
 * Standalone card to view and update the signed-in user's display name and
 * avatar. Self-contained — reads the session itself, so it can be dropped in
 * anywhere without a parent provider.
 */
export function ProfileCard({ className }: { className?: string }) {
  const { data: session, isPending: sessionPending } = authClient.useSession()
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState("")
  const nameRef = useRef<HTMLInputElement>(null)

  const ready = !sessionPending && !!session

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const name = nameRef.current?.value.trim()
    if (!name) return
    setError("")
    startTransition(async () => {
      const { error } = await authClient.updateUser({ name })
      if (error) setError(error.message ?? "Failed to update profile")
    })
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Profile</CardTitle>
        <CardDescription>Update your display name and avatar.</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          <div className="flex items-center gap-4">
            {ready ? (
              <Avatar size="lg">
                <AvatarImage src={session.user.image ?? undefined} />
                <AvatarFallback>
                  {(session.user.name || session.user.email || "U").charAt(0).toUpperCase()}
                </AvatarFallback>
              </Avatar>
            ) : (
              <Skeleton className="size-10 rounded-full" />
            )}
            <div className="text-sm">
              {ready ? (
                <>
                  <p className="font-medium">{session.user.name}</p>
                  <p className="text-muted-foreground">{session.user.email}</p>
                </>
              ) : (
                <div className="flex flex-col gap-1">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-48" />
                </div>
              )}
            </div>
          </div>

          <div className="flex flex-col gap-1.5">
            <Label htmlFor="profile-name">Display name</Label>
            {ready ? (
              <Input
                id="profile-name"
                ref={nameRef}
                defaultValue={session.user.name ?? ""}
                autoComplete="name"
                disabled={isPending}
              />
            ) : (
              <Skeleton className="h-9 w-full" />
            )}
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}

          <Button type="submit" size="sm" className="self-start" disabled={isPending || !ready}>
            {isPending ? "Saving…" : "Save changes"}
          </Button>
        </form>
      </CardContent>
    </Card>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Skeleton } from "@/components/ui/skeleton"
import { authClient } from "@/lib/auth-client"
import { useRef, useState, useTransition } from "react"

/**
 * Standalone card to change the user's email. Sends a verification link to the
 * new address; the change applies once verified.
 */
export function ChangeEmailCard({ className }: { className?: string }) {
  const { data: session, isPending: sessionPending } = authClient.useSession()
  const [isPending, startTransition] = useTransition()
  const [success, setSuccess] = useState(false)
  const [error, setError] = useState("")
  const emailRef = useRef<HTMLInputElement>(null)

  const ready = !sessionPending && !!session

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const newEmail = emailRef.current?.value.trim()
    if (!newEmail) return
    setError("")
    setSuccess(false)
    startTransition(async () => {
      const { error } = await authClient.changeEmail({
        newEmail,
        callbackURL: "/settings",
      })
      if (error) setError(error.message ?? "Failed to change email")
      else setSuccess(true)
    })
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Email address</CardTitle>
        <CardDescription>A verification link will be sent to the new address.</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="change-email">Email</Label>
            {ready ? (
              <Input
                id="change-email"
                ref={emailRef}
                type="email"
                defaultValue={session.user.email ?? ""}
                autoComplete="email"
                disabled={isPending}
                required
              />
            ) : (
              <Skeleton className="h-9 w-full" />
            )}
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}
          {success && (
            <p className="text-sm text-green-600 dark:text-green-400">
              Verification email sent. Check your inbox.
            </p>
          )}

          <Button type="submit" size="sm" className="self-start" disabled={isPending || !ready}>
            {isPending ? "Sending…" : "Update email"}
          </Button>
        </form>
      </CardContent>
    </Card>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { authClient } from "@/lib/auth-client"
import { useRef, useState, useTransition } from "react"

/**
 * Standalone card to change the user's password. On success all other sessions
 * are revoked.
 */
export function ChangePasswordCard({ className }: { className?: string }) {
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState("")
  const [success, setSuccess] = useState(false)
  const currentRef = useRef<HTMLInputElement>(null)
  const newRef = useRef<HTMLInputElement>(null)
  const confirmRef = useRef<HTMLInputElement>(null)

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const currentPassword = currentRef.current?.value
    const newPassword = newRef.current?.value
    const confirmPassword = confirmRef.current?.value
    if (!currentPassword || !newPassword || !confirmPassword) return
    if (newPassword !== confirmPassword) {
      setError("New passwords do not match")
      return
    }
    setError("")
    setSuccess(false)
    startTransition(async () => {
      const { error } = await authClient.changePassword({
        currentPassword,
        newPassword,
        revokeOtherSessions: true,
      })
      if (error) {
        setError(error.message ?? "Failed to change password")
        return
      }
      setSuccess(true)
      if (currentRef.current) currentRef.current.value = ""
      if (newRef.current) newRef.current.value = ""
      if (confirmRef.current) confirmRef.current.value = ""
    })
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Password</CardTitle>
        <CardDescription>Changing your password signs out all other sessions.</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="current-password">Current password</Label>
            <Input
              id="current-password"
              ref={currentRef}
              type="password"
              autoComplete="current-password"
              disabled={isPending}
              required
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="new-password">New password</Label>
            <Input
              id="new-password"
              ref={newRef}
              type="password"
              autoComplete="new-password"
              disabled={isPending}
              required
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="confirm-password">Confirm new password</Label>
            <Input
              id="confirm-password"
              ref={confirmRef}
              type="password"
              autoComplete="new-password"
              disabled={isPending}
              required
            />
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}
          {success && (
            <p className="text-sm text-green-600 dark:text-green-400">
              Password updated successfully.
            </p>
          )}

          <Button type="submit" size="sm" className="self-start" disabled={isPending}>
            {isPending ? "Updating…" : "Update password"}
          </Button>
        </form>
      </CardContent>
    </Card>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { useAuthList } from "@/hooks/use-auth-list"
import { authClient } from "@/lib/auth-client"
import { Laptop, LogOut, Monitor, Smartphone, Trash2 } from "lucide-react"
import { useState } from "react"

function deviceIcon(userAgent?: string | null) {
  const ua = (userAgent ?? "").toLowerCase()
  if (!ua) return <Monitor className="size-4" />
  if (ua.includes("mobile") || ua.includes("android") || ua.includes("iphone"))
    return <Smartphone className="size-4" />
  return <Laptop className="size-4" />
}

function deviceName(userAgent?: string | null) {
  if (!userAgent) return "Unknown device"
  const browser = userAgent.match(/(Chrome|Firefox|Safari|Edge|Opera)/)?.[1] ?? "Browser"
  const os = userAgent.includes("Windows")
    ? "Windows"
    : userAgent.includes("Mac")
      ? "Mac"
      : userAgent.includes("Linux")
        ? "Linux"
        : userAgent.includes("Android")
          ? "Android"
          : /iPhone|iPad/.test(userAgent)
            ? "iOS"
            : ""
  return os ? `${browser} on ${os}` : browser
}

/**
 * Standalone card listing the user's active sessions across devices, with a
 * revoke control for each and sign-out for the current one.
 */
export function SessionsCard({ className }: { className?: string }) {
  const { data: session } = authClient.useSession()
  const { data: sessions, isPending } = useAuthList(() => authClient.listSessions())
  const [revoking, setRevoking] = useState<string | null>(null)
  const [revoked, setRevoked] = useState<string[]>([])

  async function revoke(token: string) {
    setRevoking(token)
    await authClient.revokeSession({ token })
    setRevoked((prev) => [...prev, token])
    setRevoking(null)
  }

  const visible = sessions
    ?.filter((s) => !revoked.includes(s.token))
    .sort((a, b) => (a.id === session?.session.id ? -1 : b.id === session?.session.id ? 1 : 0))

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Active sessions</CardTitle>
        <CardDescription>Devices currently signed in to your account.</CardDescription>
      </CardHeader>
      <CardContent className="p-0">
        {isPending || !visible ? (
          <div className="flex flex-col gap-4 px-4 pb-4">
            {[1, 2].map((i) => (
              <div key={i} className="flex items-center gap-3">
                <Skeleton className="size-9 rounded-lg" />
                <div className="flex flex-col gap-1">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-24" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          visible.map((s, i) => {
            const isCurrent = s.id === session?.session.id
            return (
              <div key={s.id}>
                {i > 0 && <Separator />}
                <div className="flex items-center justify-between px-4 py-3">
                  <div className="flex items-center gap-3">
                    <div className="flex size-9 items-center justify-center rounded-lg bg-muted text-muted-foreground">
                      {deviceIcon(s.userAgent)}
                    </div>
                    <div>
                      <p className="text-sm font-medium">
                        {deviceName(s.userAgent)}
                        {isCurrent && (
                          <span className="ml-2 rounded-full bg-green-100 px-2 py-0.5 text-xs font-medium text-green-700 dark:bg-green-900/30 dark:text-green-400">
                            Current
                          </span>
                        )}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {s.ipAddress || "Unknown IP"} · {new Date(s.createdAt).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                  {isCurrent ? (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-muted-foreground"
                      onClick={() => authClient.signOut()}
                    >
                      <LogOut className="size-4" />
                      Sign out
                    </Button>
                  ) : (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-destructive hover:text-destructive"
                      disabled={revoking === s.token}
                      onClick={() => revoke(s.token)}
                    >
                      <Trash2 className="size-4" />
                      Revoke
                    </Button>
                  )}
                </div>
              </div>
            )
          })
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { useAuthList } from "@/hooks/use-auth-list"
import { authClient } from "@/lib/auth-client"
import { Globe } from "lucide-react"

/**
 * Standalone card listing the social / OAuth accounts linked to the user
 * (excluding the email+password credential).
 */
export function LinkedAccountsCard({ className }: { className?: string }) {
  const { data: accounts, isPending } = useAuthList(() => authClient.listAccounts())

  const social = accounts?.filter((a) => a.providerId !== "credential")

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Linked accounts</CardTitle>
        <CardDescription>Social and OAuth accounts connected to your profile.</CardDescription>
      </CardHeader>
      <CardContent>
        {isPending ? (
          <div className="flex flex-col gap-3">
            {[1, 2].map((i) => (
              <Skeleton key={i} className="h-9 w-full" />
            ))}
          </div>
        ) : social && social.length > 0 ? (
          <div className="flex flex-col gap-2">
            {social.map((account) => (
              <div
                key={account.id}
                className="flex items-center justify-between rounded-lg border px-3 py-2 text-sm"
              >
                <div className="flex items-center gap-2">
                  <Globe className="size-4 text-muted-foreground" />
                  <span className="font-medium capitalize">{account.providerId}</span>
                </div>
                <span className="text-xs text-muted-foreground">
                  Connected {new Date(account.createdAt).toLocaleDateString()}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-muted-foreground">No linked accounts yet.</p>
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"

/**
 * Fetch-on-mount helper for Better Auth list endpoints, without TanStack Query.
 *
 * Runs `fetcher` once on mount and exposes `refetch` for manual refresh after a
 * mutation. The fetcher is read through a ref so a new inline closure each
 * render does not retrigger the effect.
 *
 * @param fetcher - Returns a Better Auth response shaped as `{ data }`.
 */
export function useAuthList<T>(fetcher: () => Promise<{ data: T | null }>) {
  const fetcherRef = useRef(fetcher)
  useEffect(() => {
    fetcherRef.current = fetcher
  })

  const [data, setData] = useState<T | null>(null)
  const [isPending, setIsPending] = useState(true)

  const refetch = useCallback(async () => {
    setIsPending(true)
    const { data } = await fetcherRef.current()
    setData(data ?? null)
    setIsPending(false)
  }, [])

  useEffect(() => {
    let active = true
    fetcherRef.current().then(({ data }) => {
      if (!active) return
      setData(data ?? null)
      setIsPending(false)
    })
    return () => {
      active = false
    }
  }, [])

  return { data, isPending, refetch }
}
